//! Unrun owner execution fixtures. Dedicated fictional PostgreSQL only; no browser/provider IO.
async fn owner_execution_call(c:&mut PgConnection,path:&str,method:&str,value:Value)->Result<Value>{let route=automated_apply_agents::execution::route(path).unwrap();automated_apply_agents::execution::dispatch_body(c,route,method,None,value.to_string().as_bytes()).await}
async fn owner_legacy(c:&mut PgConnection,state:&str)->Value{let id=Uuid::new_v4();let value=json!({"id":id,"job_id":Uuid::new_v4(),"platform":"naukri","state":state,"revision":7,"fence":9,"attempts":2,"packet_id":null,"cancelled":false,"history":[],"lease_until":"2099-01-01T00:00:00Z"});browser_save(c,&format!("exec:{id}"),value.clone()).await;value}
async fn owner_preparation_policy(c:&mut PgConnection)->Value{
    let owner:Uuid=sqlx::query_scalar("SELECT id FROM candidate_profiles WHERE singleton_key='primary'").fetch_one(&mut *c).await.unwrap();
    let resources:Vec<Value>=sqlx::query_scalar("SELECT to_jsonb(r) FROM candidate_resources r WHERE candidate_profile_id=$1 ORDER BY id").bind(owner).fetch_all(&mut *c).await.unwrap();let resources=resources.into_iter().map(|v|serde_json::from_value(v).unwrap()).collect::<Vec<automated_apply_agents::resources::Resource>>();let resume=automated_apply_agents::resources::select_resume(&resources,None).unwrap().selected.unwrap();let version:i32=sqlx::query_scalar("SELECT version FROM candidate_profiles WHERE id=$1").bind(owner).fetch_one(&mut *c).await.unwrap();
    browser_save(c,"phase1_profile_confirmation",json!({"profile_id":owner,"profile_version":version,"confirmed_at":"2026-11-16T00:00:00Z"})).await;
    json!({"profile_version":version,"resume_resource_id":resume.resource_id,"resume_version":resume.resource_version,"allowed_roles":["Rust Engineer"],"allowed_locations":["Remote"],"experience_min":0,"experience_max":60})
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_start_is_atomic_idempotent_and_has_no_apply_admission(){
    let(mut c,job)=packet_service_fixture().await;sqlx::query("UPDATE jobs SET source_platform='naukri',job_url='https://www.naukri.com/job-listings-fictional-123456789012' WHERE id=$1").bind(job).execute(&mut c).await.unwrap();let start="/api/v1/execution/naukri/apply";
    let before=browser_snapshot(&mut c).await;assert_eq!(owner_execution_call(&mut c,start,"POST",json!({"job_ids":[job,Uuid::new_v4()]})).await.unwrap_err(),Failure("saved_naukri_job_required"));assert_eq!(browser_snapshot(&mut c).await,before);
    let first=owner_execution_call(&mut c,start,"POST",json!({"job_ids":[job,job]})).await.unwrap();assert_eq!(first.as_array().unwrap().len(),1);assert_eq!(first[0]["state"],"DISCOVERED");let before=browser_snapshot(&mut c).await;assert_eq!(owner_execution_call(&mut c,start,"POST",json!({"job_ids":[job]})).await.unwrap(),first);assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'exec_event:')").fetch_one(&mut c).await.unwrap(),1);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_work:') OR starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_controls_preserve_unknown_history_and_compare_current_revision(){
    let mut c=browser_fixture().await;let submitting=owner_legacy(&mut c,"SUBMITTING").await;let path=format!("/api/v1/execution/{}/control",submitting["id"].as_str().unwrap());let before=browser_snapshot(&mut c).await;assert_eq!(owner_execution_call(&mut c,&path,"POST",json!({"action":"cancel","expected_revision":6})).await.unwrap_err(),Failure("execution_revision_conflict"));assert_eq!(browser_snapshot(&mut c).await,before);
    let unknown=owner_execution_call(&mut c,&path,"POST",json!({"action":"cancel","expected_revision":7})).await.unwrap();assert_eq!(unknown["state"],"SUBMISSION_UNKNOWN");assert_eq!(unknown["fence"],10);assert!(unknown["lease_until"].is_null());let before=browser_snapshot(&mut c).await;assert_eq!(owner_execution_call(&mut c,&path,"POST",json!({"action":"resume","expected_revision":8})).await.unwrap_err(),Failure("execution_terminal_check_history"));assert_eq!(browser_snapshot(&mut c).await,before);
    let value=owner_legacy(&mut c,"PREPARING").await;let path=format!("/api/v1/execution/{}/control",value["id"].as_str().unwrap());owner_execution_call(&mut c,&path,"POST",json!({"action":"pause","expected_revision":7})).await.unwrap();let resumed=owner_execution_call(&mut c,&path,"POST",json!({"action":"resume","expected_revision":8})).await.unwrap();assert_eq!(resumed["state"],"PREPARING");assert_eq!(resumed["attempts"],0);assert_eq!(resumed["fence"],11);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_off_fences_all_preparation_and_preserves_queue_quota_and_quarantines(){
    let mut c=browser_fixture().await;execution_seed_policy(&mut c).await;let work=execution_work(&mut c,"APPLYING","executing","apply").await;let unknown=execution_work(&mut c,"SUBMISSION_UNKNOWN","unknown","apply").await;let unknown_before=browser_pref(&mut c,&unknown).await;let mut legacy=owner_legacy(&mut c,"PREPARING").await;legacy["platform"]=json!("manual_ats");let legacy_key=format!("exec:{}",legacy["id"].as_str().unwrap());browser_save(&mut c,&legacy_key,legacy).await;let quota=json!({"reservations":["spent-one","spent-two","spent-three"]});browser_save(&mut c,"apply_budget:naukri:retained",quota.clone()).await;
    owner_execution_call(&mut c,"/api/v1/execution/naukri","PUT",json!({"mode":"OFF"})).await.unwrap();assert_eq!(browser_pref(&mut c,"application_queue_policy").await["state"],"STOPPED");assert_eq!(browser_pref(&mut c,&work).await["stage"],"SUBMISSION_UNKNOWN");assert_eq!(browser_pref(&mut c,&unknown).await,unknown_before);assert_eq!(browser_pref(&mut c,&legacy_key).await["state"],"PAUSED");assert_eq!(browser_pref(&mut c,"apply_budget:naukri:retained").await,quota);assert!(browser_snapshot(&mut c).await.get("naukri_automation").is_none());
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_preparation_policy_pins_facts_and_start_does_not_start_application_queue(){
    let(mut c,_)=packet_service_fixture().await;let policy=owner_preparation_policy(&mut c).await;let path="/api/v1/execution/naukri/automation/policy";let before=browser_snapshot(&mut c).await;let mut stale=policy.clone();stale["profile_version"]=json!(999);assert_eq!(owner_execution_call(&mut c,path,"PUT",json!({"expected_revision":0,"policy":stale})).await.unwrap_err(),Failure("confirmed_profile_version_required"));assert_eq!(browser_snapshot(&mut c).await,before);
    let mut telegram=policy.clone();telegram["telegram_questions"]=json!(true);assert_eq!(owner_execution_call(&mut c,path,"PUT",json!({"expected_revision":0,"policy":telegram})).await.unwrap_err(),Failure("approved_telegram_channel_required"));let saved=owner_execution_call(&mut c,path,"PUT",json!({"expected_revision":0,"policy":policy})).await.unwrap();assert_eq!(saved["state"],"STOPPED");let legacy=owner_legacy(&mut c,"PAUSED").await;let legacy_key=format!("exec:{}",legacy["id"].as_str().unwrap());browser_save(&mut c,"exec_config:naukri",json!({"mode":"OFF"})).await;
    let running=owner_execution_call(&mut c,"/api/v1/execution/naukri/automation/control","POST",json!({"expected_revision":1,"action":"start"})).await.unwrap();assert_eq!(running["state"],"RUNNING");assert_eq!(browser_pref(&mut c,&legacy_key).await,legacy);assert_eq!(browser_pref(&mut c,"exec_config:naukri").await["mode"],"ON_DEMAND");assert!(browser_snapshot(&mut c).await.get("application_queue_policy").is_none());assert_eq!(owner_execution_call(&mut c,"/api/v1/execution/naukri/automation/control","POST",json!({"expected_revision":2,"action":"start"})).await.unwrap(),running);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_jobs_and_outbox_are_read_only_under_held_owner_fence(){
    let(mut c,job)=packet_service_fixture().await;sqlx::query("UPDATE jobs SET source_platform='naukri',job_url='https://www.naukri.com/job-listings-fictional-123456789012' WHERE id=$1").bind(job).execute(&mut c).await.unwrap();browser_save(&mut c,"agent_conversation:primary",json!({"private_message":"retained"})).await;browser_save(&mut c,"naukri_receipt:123456789012",json!({"damaged":true})).await;let event=Uuid::new_v4();browser_save(&mut c,&format!("exec_event:{event}"),json!({"id":event,"delivered":false})).await;browser_save(&mut c,"apply_event:not-legacy",json!({"delivered":false})).await;browser_save(&mut c,"exec_event:missing",json!({"not_delivered_flag":true})).await;let before=browser_snapshot(&mut c).await;let mut owner=connection().await;let mut tx=owner.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *tx).await.unwrap();sqlx::query("SET lock_timeout='100ms'").execute(&mut c).await.unwrap();let jobs=owner_execution_call(&mut c,"/api/v1/execution/naukri/jobs","GET",Value::Null).await.unwrap();assert_eq!(jobs["jobs"][0]["state"],"REJECTED");assert_eq!(jobs["jobs"][0]["reason"],"already_applied");assert_eq!(jobs["portal_search_executed"],false);let events=owner_execution_call(&mut c,"/api/v1/execution/events","GET",Value::Null).await.unwrap();assert_eq!(events.as_array().unwrap().len(),1);assert_eq!(events[0]["id"],json!(event));assert_eq!(browser_snapshot(&mut c).await,before);tx.rollback().await.unwrap();let path=format!("/api/v1/execution/events/{event}/ack");assert_eq!(owner_execution_call(&mut c,&path,"POST",Value::Null).await.unwrap(),json!({"acknowledged":true}));assert_eq!(owner_execution_call(&mut c,&path,"POST",Value::Null).await.unwrap(),json!({"acknowledged":true}));assert!(owner_execution_call(&mut c,"/api/v1/execution/events","GET",Value::Null).await.unwrap().as_array().unwrap().is_empty());
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_event_ack_failure_rolls_back_new_intent_and_owner_metadata(){
    let(mut c,job)=packet_service_fixture().await;sqlx::query("UPDATE jobs SET source_platform='naukri',job_url='https://www.naukri.com/job-listings-fictional-123456789012' WHERE id=$1").bind(job).execute(&mut c).await.unwrap();let before=browser_snapshot(&mut c).await;sqlx::raw_sql("CREATE FUNCTION fixture_owner_event_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,'exec_event:') THEN RETURN NULL; END IF; RETURN NEW; END $$;CREATE TRIGGER fixture_owner_event_drop BEFORE INSERT ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_owner_event_drop()").execute(&mut c).await.unwrap();assert_eq!(owner_execution_call(&mut c,"/api/v1/execution/naukri/apply","POST",json!({"job_ids":[job]})).await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);sqlx::raw_sql("DROP TRIGGER fixture_owner_event_drop ON owner_preferences;DROP FUNCTION fixture_owner_event_drop()").execute(&mut c).await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_http_auth_methods_validation_and_async_status_remain_separate(){
    let(mut c,job)=packet_service_fixture().await;sqlx::query("UPDATE jobs SET source_platform='naukri',job_url='https://www.naukri.com/job-listings-fictional-123456789012' WHERE id=$1").bind(job).execute(&mut c).await.unwrap();let(url,stop,server)=http_fixture_values(browser_values()).await;let http=client();let path=format!("{url}/api/v1/execution/naukri/apply");let data=json!({"job_ids":[job]});assert_eq!(http.post(&path).json(&data).send().await.unwrap().status(),401);assert_eq!(http.post(&path).bearer_auth(HOST_TOKEN).header("x-agent-client",BROWSER_EXTENSION).json(&data).send().await.unwrap().status(),403);assert_eq!(http.post(&path).bearer_auth(HOST_TOKEN).json(&data).send().await.unwrap().status(),202);assert_eq!(http.get(&path).bearer_auth(HOST_TOKEN).send().await.unwrap().status(),405);assert_eq!(http.post(format!("{url}/api/v1/execution/not-a-uuid/control")).bearer_auth(HOST_TOKEN).json(&json!({"action":"pause","expected_revision":1})).send().await.unwrap().status(),422);assert_eq!(http.post(format!("{url}/api/v1/execution/events/{}/ack",Uuid::new_v4())).bearer_auth(HOST_TOKEN).json(&json!({})).send().await.unwrap().status(),404);let denied=http.put(format!("{url}/api/v1/execution/naukri")).bearer_auth(HOST_TOKEN).json(&json!({"submission_permission":true})).send().await.unwrap();assert_eq!(denied.status(),409);stop.cancel();server.await.unwrap();
}
